import { VisitNoteDao } from '../../persistence/VisitNoteDao';

export interface VisitNote {
  author: string;
  text: string;
  writtenAt: Date;
}

export class VisitNotesService {
  constructor(private readonly notes: VisitNoteDao) {}

  async write(appointmentId: string, author: string, text: string): Promise<VisitNote> {
    const row = await this.notes.add({ id: `${appointmentId}:${Date.now()}`, appointmentId, author, text: text.trim(), writtenAt: new Date() });
    return { author: row.author, text: row.text, writtenAt: row.writtenAt };
  }

  async notesFor(appointmentId: string, context?: NotesForContextDto): Promise<VisitNote[]> {
    const rows = await this.notes.forAppointment(appointmentId);
    return rows.sort((a, b) => a.writtenAt.getTime() - b.writtenAt.getTime()).map((r) => ({ author: r.author, text: r.text, writtenAt: r.writtenAt }));
  }
}

export interface NotesForContextDto {
  readonly requestId?: string;
}

