import { DomainError } from './domain-error';

export class Course {
  id: string;
  title: string;
  capacity: number;
  enrolled: number;
  published: boolean;

  constructor(id: string, title: string, capacity: number, enrolled: number, published: boolean) {
    this.id = id;
    this.title = title;
